class TierModel(BaseModel):
    """
    Volume-based pricing tier that defines different rates based on usage levels. Tiers enable graduated or volume pricing where the rate changes as usage increases. Each tier specifies a usage range and corresponding pricing. Tiers are primarily used within RatingAggregation for modern usage-based billing. They also appear in PeriodChargeResource to show which tier was applied to a specific charge
    """

    flatAmount: Optional[float] = Field(
        None,
        description='A fixed charge applied when usage reaches this tier. For example, a $100 base fee for the 1000-5000 unit tier. Can be combined with unitAmount',
        examples=[100.0],
    )
    id: Optional[str] = Field(
        None,
        description='The unique identifier of the pricing tier',
        examples=['af75417c71d24e708f506596ce5ab675'],
    )
    name: str = Field(
        ...,
        description='The name of the pricing tier for identification and display purposes',
        examples=['First 1000 units'],
    )
    startingFrom: Optional[float] = Field(
        None,
        description='The lower bound of the usage range for this tier (inclusive). For example, 0 for the first tier, 1000 for the second tier. If null, starts from 0',
        examples=[1000],
    )
    unitAmount: Optional[float] = Field(
        None,
        description='The per-unit price for usage within this tier. For example, $0.10 per API call for the first 1000 calls. Used for usage-based pricing',
        examples=[0.1],
    )
    upTo: Optional[float] = Field(
        None,
        description='The upper bound of the usage range for this tier (exclusive). For example, 1000 means this tier applies up to but not including 1000 units. If null, this tier has no upper limit',
        examples=[5000],
    )


